def _story_ids():
    return list(STORIES.keys())

def _progress_percent(part_index,total):
    return min(100, round(((part_index+1)/total)*100)) if total else 0

def _keyboard(story_id,part_index):
    story=STORIES[story_id]
    total=len(story["parts"])
    if part_index < total-1:
        return InlineKeyboardMarkup([[InlineKeyboardButton("➡️ Continue", callback_data=f"mb_story|{story_id}|{part_index+1}")]])
    return InlineKeyboardMarkup([[InlineKeyboardButton("🌸 Finish", callback_data="mb_story|menu|0")]])

def _menu_keyboard(page):
    ids=_story_ids(); total_pages=max(1,(len(ids)+STORIES_PER_PAGE-1)//STORIES_PER_PAGE)
    page=max(0,min(page,total_pages-1)); chunk=ids[page*STORIES_PER_PAGE:(page+1)*STORIES_PER_PAGE]
    rows=[[InlineKeyboardButton(f"{STORIES[s]['emoji']} {STORIES[s]['title']}",callback_data=f"mb_story|open|{s}")] for s in chunk]
    nav=[]
    if page>0: nav.append(InlineKeyboardButton("⬅️",callback_data=f"mb_story|menu|{page-1}"))
    if page<total_pages-1: nav.append(InlineKeyboardButton("➡️",callback_data=f"mb_story|menu|{page+1}"))
    if nav: rows.append(nav)
    return InlineKeyboardMarkup(rows),page,total_pages

async def _show_part(update,story_id,part_index):
    story=STORIES[story_id]; total=len(story["parts"]); part_index=max(0,min(part_index,total-1))
    percent=_progress_percent(part_index,total)
    text=f"Part {part_index+1}/{total} • {percent}%\n\n{story['parts'][part_index]}"
    markup=_keyboard(story_id,part_index)
    if update.callback_query: await update.callback_query.edit_message_text(text,reply_markup=markup)
    elif update.effective_message: await update.effective_message.reply_text(text,reply_markup=markup)

async def _show_menu(update,page=0):
    markup,page,total_pages=_menu_keyboard(page)
    text="📖 Stories"
    if update.callback_query: await update.callback_query.edit_message_text(text,reply_markup=markup)
    elif update.effective_message: await update.effective_message.reply_text(text,reply_markup=markup)

async def story_command(update,context):
    context.user_data.pop("mb_story",None)
    await _show_menu(update,0)

async def handle_story_callback(update,context):
    q=update.callback_query
    if not q: return
    data=(q.data or "").split("|")
    if data[:2]==["mb_story","start"]:
        await q.answer(); return await story_command(update,context)
    if len(data)==3 and data[1]=="menu":
        await q.answer();
        try: page=int(data[2])
        except Exception: page=0
        return await _show_menu(update,page)
    if len(data)==3 and data[1]=="open":
        sid=data[2]
        if sid not in STORIES: await q.answer("Story nahi mili.",show_alert=True); return
        await q.answer(); context.user_data["mb_story"]={"story_id":sid,"part":0}
        return await _show_part(update,sid,0)
    if len(data)==3 and data[0]=="mb_story":
        sid,node=data[1],data[2]
        if sid not in STORIES: await q.answer("Story nahi mili.",show_alert=True); return
        try: idx=int(node)
        except Exception: await q.answer("Story dobara open karo.",show_alert=True); return
        total=len(STORIES[sid]["parts"])
        if 0<=idx<total:
            await q.answer(); context.user_data["mb_story"]={"story_id":sid,"part":idx}; return await _show_part(update,sid,idx)
    await q.answer("Story dobara open karo. 📖",show_alert=True)

def register_story_handlers(application):
    return application
